		t.Fatalf("GetToken() error = %v", err)
	}
	if got != "file-token" {
		t.Fatalf("GetToken() = %q, want %q", got, "file-token")
	}

	info, err := os.Stat(storeFile)
	if err != nil {
		t.Fatalf("stat store file: %v", err)
	}
	if got := info.Mode().Perm(); got != 0o600 {
		t.Fatalf("store file mode = %v, want 0600", got)
	}
}

